def main() -> int:
    parser = argparse.ArgumentParser(description='Rebuild the packaged housing revision')
    parser.add_argument('--out', type=Path, default=Path('regenerated'))
    parser.add_argument('--job-id', default='rebuilt-housing')
    args = parser.parse_args()
    config = ProjectConfig.model_validate_json(CONFIG_JSON)
    manifest = generate_artifacts(config, args.out, job_id=args.job_id)
    print((args.out.resolve() / manifest['job_id']).as_posix())
    return 0

if __name__ == '__main__':
    raise SystemExit(main())
